require_once __DIR__.'/includes/bootstrap.php';if(user())go('index.php');$errors=[];$name='';$email='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');
if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(strlen($pw)<8)$errors[]='Password must be at least 8 characters.';
if(!$errors){$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='That email is already registered.';else{$s=db()->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'student')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'full_name'=>$name,'email'=>$email,'role'=>'student'];flash('Welcome to CampusConnect.');go('index.php');}}}
$pageTitle='Create account';require __DIR__.'/includes/header.php';?>
<div class="auth-wrap"><div class="auth-card"><span class="pill">STUDENT ACCOUNT</span><h1 class="h2 fw-bold mt-3">Join CampusConnect</h1><p class="text-secondary">Create an account to register for campus events.</p><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(token())?>"><div class="mb-3"><label class="form-label" for="full_name">Full name</label><input class="form-control" id="full_name" name="full_name" required maxlength="100" value="<?=e($name)?>"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" type="email" name="email" required value="<?=e($email)?>"></div><div class="mb-4"><label class="form-label" for="password">Password</label><input class="form-control" id="password" type="password" name="password" minlength="8" required><div class="form-text">At least 8 characters.</div></div><button class="btn btn-primary btn-lg w-100">Create account</button></form><p class="text-center mt-3 mb-0">Already registered? <a href="login.php">Sign in</a></p></div></div><?php require __DIR__.'/includes/footer.php';?>